{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.j7an/nexus-mcp",
  "description": "Invoke CLI agents (Codex, Claude, OpenCode) as MCP tools with parallel execution",
  "version": "1.0.2",
  "repository": {
    "url": "https://github.com/j7an/nexus-mcp",
    "source": "github"
  },
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "nexus-mcp",
      "version": "1.0.2",
      "runtimeHint": "uvx",
      "runtimeArguments": [
        {
          "type": "positional",
          "value": "--python",
          "isRequired": true
        },
        {
          "type": "positional",
          "value": "3.13",
          "isRequired": true
        }
      ],
      "transport": {
        "type": "stdio"
      }
    }
  ]
}
